CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK (length(display_name)<=100), preferences text NOT NULL DEFAULT '' CHECK(length(preferences)<=600));
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY profile_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK(id=auth.uid());
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_support_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id) ON CONFLICT DO NOTHING; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.create_support_profile() FROM PUBLIC;
CREATE TRIGGER support_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_support_profile();
CREATE TABLE public.support_conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), processing_token uuid, processing_until timestamptz);
GRANT SELECT ON public.support_conversations TO authenticated; GRANT ALL ON public.support_conversations TO service_role;
ALTER TABLE public.support_conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY conversation_read ON public.support_conversations FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.support_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES public.support_conversations(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('user','assistant')), parts jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.support_messages TO authenticated; GRANT ALL ON public.support_messages TO service_role;
ALTER TABLE public.support_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY message_read ON public.support_messages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.support_conversations c WHERE c.id=conversation_id AND c.user_id=auth.uid()));
CREATE TABLE public.support_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, order_number text NOT NULL, customer_email text NOT NULL, status text NOT NULL, items_summary text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,order_number));
GRANT SELECT ON public.support_orders TO authenticated; GRANT ALL ON public.support_orders TO service_role;
ALTER TABLE public.support_orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY order_owner_read ON public.support_orders FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.support_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL, user_id uuid NOT NULL, conversation_id uuid NOT NULL REFERENCES public.support_conversations(id), name text NOT NULL CHECK(length(name) BETWEEN 2 AND 100), email text NOT NULL CHECK(length(email)<=254), order_number text NOT NULL DEFAULT '' CHECK(length(order_number)<=100), summary text NOT NULL CHECK(length(summary) BETWEEN 10 AND 2000), transcript jsonb NOT NULL, status text NOT NULL DEFAULT 'requested' CHECK(status IN('requested','in_progress','closed')), notification_status text NOT NULL DEFAULT 'pending_configuration' CHECK(notification_status IN('pending_configuration','sent','failed','suppressed')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,request_id));
GRANT SELECT ON public.support_tickets TO authenticated; GRANT ALL ON public.support_tickets TO service_role;
ALTER TABLE public.support_tickets ENABLE ROW LEVEL SECURITY;
CREATE POLICY ticket_owner_read ON public.support_tickets FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.open_support_conversation() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; INSERT INTO public.support_conversations(user_id) VALUES(auth.uid()) ON CONFLICT(user_id) DO UPDATE SET user_id=EXCLUDED.user_id RETURNING id INTO cid; RETURN cid; END; $$;
REVOKE ALL ON FUNCTION public.open_support_conversation() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.open_support_conversation() TO authenticated;
CREATE FUNCTION public.begin_support_turn(_conversation_id uuid,_token uuid,_parts jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR jsonb_typeof(_parts)<>'array' OR length(_parts::text)>12000 THEN RAISE EXCEPTION 'Invalid request'; END IF; UPDATE public.support_conversations SET processing_token=_token,processing_until=now()+interval '3 minutes' WHERE id=_conversation_id AND user_id=auth.uid() AND (processing_until IS NULL OR processing_until<now()); IF NOT FOUND THEN RAISE EXCEPTION 'Conversation busy or unavailable'; END IF; INSERT INTO public.support_messages(conversation_id,role,parts) VALUES(_conversation_id,'user',_parts); END; $$;
REVOKE ALL ON FUNCTION public.begin_support_turn(uuid,uuid,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.begin_support_turn(uuid,uuid,jsonb) TO authenticated;
CREATE FUNCTION public.finish_support_turn(_conversation_id uuid,_token uuid,_parts jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE mid uuid; BEGIN UPDATE public.support_conversations SET processing_token=NULL,processing_until=NULL WHERE id=_conversation_id AND user_id=auth.uid() AND processing_token=_token; IF NOT FOUND THEN RAISE EXCEPTION 'Conversation unavailable'; END IF; IF _parts IS NOT NULL THEN IF jsonb_typeof(_parts)<>'array' OR length(_parts::text)>20000 THEN RAISE EXCEPTION 'Invalid response'; END IF; INSERT INTO public.support_messages(conversation_id,role,parts) VALUES(_conversation_id,'assistant',_parts) RETURNING id INTO mid; END IF; RETURN mid; END; $$;
REVOKE ALL ON FUNCTION public.finish_support_turn(uuid,uuid,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.finish_support_turn(uuid,uuid,jsonb) TO authenticated;
CREATE FUNCTION public.request_support_handoff(_request_id uuid,_conversation_id uuid,_name text,_email text,_order_number text,_summary text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid; BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.support_conversations WHERE id=_conversation_id AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF _email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'Invalid email'; END IF; INSERT INTO public.support_tickets(request_id,user_id,conversation_id,name,email,order_number,summary,transcript) VALUES(_request_id,auth.uid(),_conversation_id,_name,_email,_order_number,_summary,COALESCE((SELECT jsonb_agg(jsonb_build_object('role',role,'parts',parts) ORDER BY created_at,id) FROM public.support_messages WHERE conversation_id=_conversation_id),'[]'::jsonb)) ON CONFLICT(user_id,request_id) DO UPDATE SET request_id=EXCLUDED.request_id RETURNING id INTO tid; RETURN tid; END; $$;
REVOKE ALL ON FUNCTION public.request_support_handoff(uuid,uuid,text,text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.request_support_handoff(uuid,uuid,text,text,text,text) TO authenticated;